-- MTH213 topic bank built from the course notes and the existing introduction question set.
-- This imports 126 questions across 15 topics.
-- Safe to rerun: the same IDs are updated instead of duplicated.
begin;
on conflict (id) do update set
  course = excluded.course,
  topic = excluded.topic,
  prompt = excluded.prompt,
  d = excluded.d,
  options = excluded.options,
  explain = excluded.explain;
commit;
